-- Ṛtam — 13 more verified temples: the complete Nava Tirupati circuit (9
-- Vaishnava shrines on the Thamirabarani, Tamil Nadu) and the 4 missing
-- Pancharanga Kshetrams (Srirangam was already present) — five temples to
-- Ranganatha strung along the Kaveri from Karnataka to Tamil Nadu.

insert into public.temples (
  name, deity, sampradaya, significance, country, state, district, town, latitude, longitude, sandhya_friendly, sandhya_notes, samidhadhanam_friendly, samidhadhanam_notes, food_tier, food_source_name, food_distance_km, nearest_river_name, river_distance_km, best_season_notes, sthala_purana, sthala_purana_source, architecture_style, construction_century, status
) values
(
  'Srivaikuntanathan Perumal Temple, Srivaikuntam', 'Vaikunthanathar (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Srivaikuntam', 8.631167, 77.909611, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 0.2, 'Oct–Feb.', 'One of the Nava Tirupati, nine Vishnu shrines strung along the Thamirabarani river and each counted among the 108 Divya Desams glorified by the Alvar poet-saints. Vishnu is worshipped here as Vaikunthanathar with his consort as Vaikunthavalli, and devotional tradition links this temple to Surya (the Sun) within the Nava Tirupati''s parallel association with the nine planets.', 'Local/regional tradition', null, null, 'approved'
),
(
  'Vijayasana Perumal Temple, Natham', 'Vijayasana Perumal (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Natham', 8.637056, 77.924139, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 1, 'Oct–Feb.', 'One of the Nava Tirupati and a Divya Desam, also called Thiruvaragunamangai. Tradition holds a Brahmin named Vedhavi performed penance here chanting the "Aasana mantra," and Vishnu — pleased with his devotion — appeared before him and granted him moksha; hence the deity is known as Vijayasana Perumal, with Lakshmi as Varagunavalli. Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Chandra (the Moon).', 'Local/regional tradition', null, null, 'approved'
),
(
  'Vaithamanidhi Perumal Temple, Thirukkolur', 'Vaithamanidhi Perumal (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Thirukkolur', 8.59667, 77.95778, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 1, 'Oct–Feb.', 'One of the Nava Tirupati and a Divya Desam, sometimes called Kuberasthalam, where Vishnu reclines as Vaithamanidhi Perumal. Thirukkolur is also revered as the birthplace of Madurakavi Alvar, one of the twelve Alvar poet-saints. Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Mangala (Mars).', 'Local/regional tradition', null, null, 'approved'
),
(
  'Thirupuliyangudi Perumal Temple', 'Bhoomipalar (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Thirupuliyangudi', 8.63975, 77.932778, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 1, 'Oct–Feb.', 'One of the Nava Tirupati and a Divya Desam praised in the hymns of Nammalvar. Vishnu reclines here as Bhoomipalaka Perumal with a lotus stem rising from his navel, Brahma seated atop its bloom — the classic Vaishnava image of creation — while his consort is worshipped as Pulingudivalli. Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Budha (Mercury).', 'Local/regional tradition', null, null, 'approved'
),
(
  'Adinatha Perumal Temple, Alwarthirunagari', 'Adinathar (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Alwarthirunagari', 8.607111, 77.938306, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 1, 'Oct–Feb.', 'The most prominent of the nine Nava Tirupati shrines and a Divya Desam, since Alwarthirunagari is revered as the birthplace of Nammalvar, considered the foremost among the twelve Alvar poet-saints and the composer of a large share of the Nalayira Divya Prabandham. Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Guru (Jupiter).', 'Local/regional tradition', null, null, 'approved'
),
(
  'Makara Nedunkuzhaikathar Temple, Thenthiruperai', 'Makara Nedunkuzhaikathar (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Thenthiruperai', 8.603222, 77.986028, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 0.5, 'Oct–Feb.', 'One of the Nava Tirupati and a Divya Desam. Tradition holds that Bhoodevi (the earth goddess) performed penance here and discovered a pair of makara-shaped (crocodile-form) earrings, which Vishnu then wore — giving him the name Makara Nedunkuzhaikathar, "he of the long makara earrings." Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Shukra (Venus), and devotees pray here for relief from Venus-related afflictions.', 'Local/regional tradition', null, null, 'approved'
),
(
  'Mayakoothan Perumal Temple, Perunkulam', 'Mayakoothan (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Perunkulam', 8.641806, 77.993944, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 1, 'Oct–Feb.', 'One of the Nava Tirupati and a Divya Desam, following the Thenkalai school of Sri Vaishnavism and Pancharatra agama. Within the Nava Tirupati''s parallel association with the nine planets, this shrine — also known as Thirukulandhai — is regarded as a Sani Sthalam, linked to Shani (Saturn), and is visited by devotees seeking relief from Saturn-related hardship.', 'Local/regional tradition', null, null, 'approved'
),
(
  'Devapiran Temple, Tholaivillimangalam', 'Devapiran (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Tholaivillimangalam', 8.61111, 77.97222, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 0.3, 'Oct–Feb.', 'One of a pair of adjacent shrines at Tholaivillimangalam known together as Irattai Thiruppathi ("twin Tirupati"), the other being the neighbouring Aravindalochanar Temple — together completing the nine Nava Tirupati. Vishnu is worshipped here as Devapiran with his consort as Karunthadankanni. Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Rahu.', 'Local/regional tradition', null, null, 'approved'
),
(
  'Aravindalochanar Temple, Tholaivillimangalam', 'Aravindalochanar (Vishnu)', 'Vaishnava', array['Nava Tirupati'], 'India', 'Tamil Nadu', 'Thoothukudi', 'Tholaivillimangalam', 8.61111, 77.97222, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Thamirabarani', 0.3, 'Oct–Feb.', 'The second of the adjacent ''Irattai Thiruppathi'' (twin Tirupati) shrines at Tholaivillimangalam, alongside the neighbouring Devapiran Temple — together completing the nine Nava Tirupati, all Divya Desams on the Thamirabarani. Within the Nava Tirupati''s parallel association with the nine planets, this shrine is linked to Ketu.', 'Local/regional tradition', null, null, 'approved'
),
(
  'Ranganathaswamy Temple, Srirangapatna', 'Ranganatha (Adi Ranga)', 'Vaishnava', array['Pancharanga Kshetram'], 'India', 'Karnataka', 'Mandya', 'Srirangapatna', 12.424722, 76.679722, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Kaveri', 0.1, 'Oct–Feb.', 'The first of the five Pancharanga Kshetrams — temples to Ranganatha (a form of Vishnu) strung along the Kaveri river — earning this shrine the name Adi Ranga, "the first Ranga," counting downstream toward Srirangam. Built in 984 CE by Tirumalaiah, a local chief under the Western Ganga dynasty, on the site of an older shrine; in the 12th century the Hoysala king Vishnuvardhana granted the surrounding village to the philosopher-saint Ramanujacharya.', 'Local/regional tradition', 'Dravidian (Western Ganga / Hoysala)', 10, 'approved'
),
(
  'Ranganathaswamy Temple, Shivanasamudra', 'Ranganatha (Madhya Ranga)', 'Vaishnava', array['Pancharanga Kshetram'], 'India', 'Karnataka', 'Chamarajanagar', 'Shivanasamudra', 12.270556, 77.169722, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Kaveri', 0.1, 'Oct–Feb.', 'The second of the five Pancharanga Kshetrams on the Kaveri, known as Madhya Ranga ("the middle Ranga") for its position between Srirangapatna (Adi Ranga) and Srirangam (Antya Ranga). Ranganatha here is worshipped in his youthful form, and is affectionately called Mohana Ranga or Jaganmohana Ranga. Like its counterparts, the temple stands on an island formed by the Kaveri, and forms part of the single-day Tri Ranga Darshana pilgrimage across all three Karnataka-to-Tamil Nadu Ranga shrines.', 'Local/regional tradition', 'Dravidian', null, 'approved'
),
(
  'Appakkudathaan Perumal Temple, Koviladi', 'Appakkudathaan (Vishnu)', 'Vaishnava', array['Pancharanga Kshetram'], 'India', 'Tamil Nadu', 'Thanjavur', 'Koviladi', 10.839444, 78.889444, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Kaveri', 0.2, 'Oct–Feb.', 'One of the five Pancharanga Kshetrams on the Kaveri and a Divya Desam glorified in the Nalayira Divya Prabandham, also known by its old name Thiruppernagar. The shrine, approached by a flight of 21 steps up an elevated structure, carries inscriptions dating to the reign of the Chola king Aditya I, with further contributions from later Medieval Chola rulers.', 'Local/regional tradition', 'Dravidian (Chola)', 9, 'approved'
),
(
  'Sarangapani Temple, Kumbakonam', 'Sarangapani (Vishnu)', 'Vaishnava', array['Pancharanga Kshetram'], 'India', 'Tamil Nadu', 'Thanjavur', 'Kumbakonam', 10.95944, 79.37472, 'unknown', null, 'unknown', null, 'unknown', null, null, 'Kaveri', 1, 'Oct–Feb; the temple car festival (Panguni, Mar/Apr) is a major local event.', 'The largest Vishnu temple in Kumbakonam and one of the five Pancharanga Kshetrams on the Kaveri, and a Divya Desam. Its rajagopuram rises about 173 feet across eleven tiers — the third-tallest gopuram among all Divya Desams, after Srirangam and Srivilliputhur. Sarangapani is also counted among the Pancha Kshetras where Lakshmi is held to have been born as Bhargavi, daughter of the sage Bhrigu. The earliest inscriptions here date to the late Chola period, with major expansion under the Vijayanagara and Nayaka rulers.', 'Local/regional tradition', 'Dravidian (Chola, Vijayanagara, Nayaka)', 12, 'approved'
);

