insert into public.temple_festivals (temple_id, name, month, secondary_month, notes) values
((select id from public.temples where name = 'Sarangapani Temple, Kumbakonam'), 'Panguni car festival', 3, 4, 'The temple''s annual rathotsavam (chariot festival).');
